import { Session } from 'node:inspector/promises';
import { mkdtemp, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { resolve } from 'node:path';
const repo = process.cwd();
const { initializeActiveFixture } = await import(resolve(repo, 'scripts/evaluation/lib/context-quality-active-fixture.mjs'));
const { activeWorker } = await import(resolve(repo, 'scripts/evaluation/lib/context-quality-active-worker.mjs'));
const { SQLiteEventStore } = await import(resolve(repo, 'packages/event-store-sqlite/dist/index.js'));
const parent = await mkdtemp(resolve(tmpdir(), 'lervo-recording-profile-'));
const results = [];
try {
 for (const arm of ['control', 'candidate']) {
  const root=resolve(parent,arm); await initializeActiveFixture(root);
  let opens=0,openMs=0,integrityCalls=0,integrityMs=0;
  const originalOpen=SQLiteEventStore.open, originalVerify=SQLiteEventStore.prototype.verifyIntegrity;
  SQLiteEventStore.open=async function(...args) { const start=performance.now(); opens++; try {return await originalOpen.apply(this,args);} finally {openMs+=performance.now()-start;} };
  SQLiteEventStore.prototype.verifyIntegrity=function(...args) {const start=performance.now(); integrityCalls++;try{return originalVerify.apply(this,args);}finally{integrityMs+=performance.now()-start;}};
  const session = new Session(); session.connect(); await session.post('Profiler.enable');await session.post('Profiler.start');
  let worker, profile;
  try {worker=await activeWorker(root,arm,'concurrent',4096,{warmups:2,samples:30,concurrency:4}); ({profile}=await session.post('Profiler.stop'));}
  finally {SQLiteEventStore.open=originalOpen;SQLiteEventStore.prototype.verifyIntegrity=originalVerify;session.disconnect();}
  const nodes=new Map(profile.nodes.map(n=>[n.id,n])); const counts=new Map();
  for(const id of profile.samples ?? []) {const f=nodes.get(id).callFrame;const url=f.url.startsWith('file://'+repo+'/')?f.url.slice(repo.length+8):f.url.startsWith('node:')?f.url:'runtime';const key=JSON.stringify([f.functionName,url,f.lineNumber+1]);counts.set(key,(counts.get(key)??0)+1);}
  results.push({arm,requests:128,opens,openMs,integrityCalls,integrityMs,semanticValid:worker.semanticValid,events:worker.eventCount,integrity:worker.integrity,sampledFrames:profile.samples?.length,topSelfSamples:[...counts].sort((a,b)=>b[1]-a[1]).slice(0,25).map(([key,count])=>[...JSON.parse(key),count])});
 }
 await writeFile('/tmp/lervo-priority4-recording-profile.json',JSON.stringify({diagnosticOnly:true,method:'Node inspector CPU samples plus wrapped public SQLiteEventStore open/integrity; concurrent4,2warmups,30samples,control first,isolated different roots; timings overlap and cannot be added or used as acceptance',results},null,2));
}finally{await rm(parent,{recursive:true,force:true});}
